DELIMITER $$
CREATE PROCEDURE sp_borrow(IN p_rno CHAR(8),
  IN p_bno CHAR(10), OUT msg VARCHAR(20))
BEGIN
  DECLARE n INT DEFAULT 0;
  SELECT stock INTO n FROM book WHERE bno = p_bno;
  IF n > 0 THEN
    INSERT INTO borrow(rno, bno, bdate)
      VALUES (p_rno, p_bno, CURDATE());
    UPDATE book SET stock = stock - 1 WHERE bno = p_bno;
    SET msg = '借阅成功';
  ELSE
    SET msg = '不能借阅';
  END IF;
END $$
DELIMITER ;
CALL sp_borrow('R001', 'B001', @m);
SELECT @m;

DELIMITER $$
CREATE FUNCTION fn_total(p_gno CHAR(6))
  RETURNS DECIMAL(10,2)
BEGIN
  DECLARE t DECIMAL(10,2);
  SELECT SUM(g.price * o.qty) INTO t
    FROM goods AS g JOIN orders AS o ON g.gno = o.gno
    WHERE g.gno = p_gno;
  IF t IS NULL THEN
    SET t = 0;
  END IF;
  RETURN t;
END $$
DELIMITER ;
SELECT gno, gname, fn_total(gno) AS 销售总额 FROM goods;
DROP FUNCTION fn_total;

CREATE TRIGGER tr_order_ins AFTER INSERT ON orders
FOR EACH ROW
  UPDATE goods SET stock = stock - NEW.qty
  WHERE gno = NEW.gno;
CREATE TRIGGER tr_order_del AFTER DELETE ON orders
FOR EACH ROW
  UPDATE goods SET stock = stock + OLD.qty
  WHERE gno = OLD.gno;
DROP TRIGGER tr_order_del;

CREATE TABLE salary_log (
  eno         CHAR(6),
  old_sal     DECIMAL(8,2),
  new_sal     DECIMAL(8,2),
  change_time DATETIME
);
DELIMITER $$
CREATE TRIGGER tr_sal_upd AFTER UPDATE ON emp
FOR EACH ROW
BEGIN
  IF NEW.salary <> OLD.salary THEN
    INSERT INTO salary_log
      VALUES (OLD.eno, OLD.salary, NEW.salary, NOW());
  END IF;
END $$
DELIMITER ;
UPDATE emp SET salary = salary + 300 WHERE eno = 'E001';
